-- >>> Hand-written (not generated by drizzle-kit; keep it when regenerating).
-- The organization name that earlier versions saved as their default, the
-- app's former product name, becomes the new default "IAM". Matched by its
-- MD5 only, so that no other name changes; a name an admin chose stays.
UPDATE "iam_appsettings"
SET "organization_name" = 'IAM'
WHERE md5("organization_name") = '8433a6f7d6dd42e2af4b41bb96b3142a';
-- <<< End of hand-written SQL.
